export function getCapability(id:string):CapabilityDescriptor|undefined{return builtinCapabilities.find(c=>c.id===id);}
export function discoverCapabilities(query:{category?:CapabilityDescriptor["category"];renderer?:string;maturity?:CapabilityDescriptor["maturity"]}):CapabilityDescriptor[]{
  return builtinCapabilities.filter(c=>(!query.category||c.category===query.category)&&(!query.renderer||c.renderers.some(r=>r===query.renderer))&&(!query.maturity||c.maturity===query.maturity));
}
